     function h(tag, props = {}, ...children) {
       const element = document.createElement(tag);

       Object.entries(props).forEach(([key, value]) => {
         if (key === "className") {
           element.className = value;
         } else if (key === "text") {
           element.textContent = value;
         } else if (key.startsWith("on") && typeof value === "function") {
           element.addEventListener(key.slice(2).toLowerCase(), value);
         } else if (value !== undefined && value !== null) {
           element.setAttribute(key, value);
         }
       });

       children.flat().forEach((child) => {
         if (child === null || child === undefined || child === false) {
           return;
         }

         element.append(child.nodeType ? child : document.createTextNode(String(child)));
       });

       return element;
     }

     function ChoiceOption({ questionId, choice }) {
       const checkboxId = `${questionId}-${choice.id}`;

       return h(
         "label",
         { className: "choice", for: checkboxId },
         h("input", {
           type: "checkbox",
           id: checkboxId,
           name: questionId,
           value: choice.id
         }),
         h("span", { className: "choice-title", text: choice.label })
       );
     }

     function QuestionField({ question, index }) {
       const helpId = question.helpText ? `${question.id}-help` : undefined;

       return h(
         "div",
         { className: "form-field" },
         h(
