           helpId ? { "aria-describedby": helpId } : {},
           h("legend", { text: `${index + 1}. ${question.prompt}` }),
           h("p", { className: "question-meta", text: "Select all answers that apply." }),
           question.helpText
             ? h("p", { className: "help-text", id: helpId, text: question.helpText })
             : null,
           h(
             "div",
             { className: "choices" },
